css:
:root{
  --page-top: 5mm;
  --page-lr: 10mm;
  --page-bottom: 3mm;
}

@page{
  size: A4;
  margin: var(--page-top) var(--page-lr) var(--page-bottom) var(--page-lr);
}

html, body{
  margin: 0;
  padding: 0;
  direction: rtl;
  color: #000;
  font-family: "Arabic Typesetting","Traditional Arabic",Arial,sans-serif;
}

.print-format{
  padding: 0 !important;
  margin: 0 !important;
}

.page-table{
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

/* Footer repeats */
.page-table tfoot{ display: table-footer-group; }

.content-cell, .footer-cell{ padding: 0; }

.pagebreak{ page-break-before: always; }

hr{
  border: 1px solid #000;
  margin: 5px 0 8px 0;
}

.nowrap{ white-space: nowrap; }

.header-table{ width:100%; border-collapse:collapse; }
.header-table td{ vertical-align:middle; }
.header-text{ text-align:center; line-height:1.4; }
.header-text .line1{ font-size:28px; font-weight:bold; }
.header-text .line2, .header-text .line3{ font-size:24px; }
.header-logo{ width:120px; text-align:left; }
.header-logo img{ height:90px; display:block; }

.info-table{ width:100%; border-collapse:collapse; margin-bottom:8px; }
.info-table td{ width:50%; vertical-align:top; }
.info-table p{ margin:2px 0; }

/* keep title with body (reduces orphan pages) */
.term-section{ margin-top:10px; page-break-inside: avoid; }
.term-title{
  background:#f0f0f0;
  border:1px solid #ddd;
  padding:4px 6px;
  font-size:18px;
  font-weight:bold;
  page-break-after: avoid;
}
.term-body{
  border:1px solid #ddd;
  padding:6px 8px;
  white-space: pre-line;
  line-height:1.25;
}

.receipt-table{
  width:100%;
  border-collapse:collapse;
  table-layout:fixed;
  font-size:11px;
  margin:6px 0;
}
.receipt-table th, .receipt-table td{
  border:1px solid #000;
  padding:4px;
  text-align:right;
  white-space:normal;
  overflow-wrap:anywhere;
  word-break:break-word;
}
.receipt-table th{ background:#d9d9d9; }
.receipt-table tbody tr:nth-child(even){ background:#f9f9f9; }
.receipt-table tfoot td{ background:#efefef; font-weight:bold; }

/* footer compact so it doesn't push itself to a new page */
.footer-dots{
  border-top: 1px dotted #000;
  margin: 0.5mm 0 0.5mm 0;
  height: 0;
}
.footer-table{
  width:100%;
  border-collapse:collapse;
  table-layout:fixed;
  font-size:11px;
  line-height:0.95;
}
.footer-table td{ padding:0; border:0; vertical-align:top; }
.footer-right{ text-align:right; width:50%; }
.footer-left{ text-align:left; direction:ltr; width:50%; }
